window.__SD=(window.__SD||[]).concat([{"slug": "andrew-critch", "name": "Andrew Critch", "category": "academic-alignment", "current_role": "CEO and co-founder, Encultured AI (dba HealthcareAgents); part-time Research Scientist, CHAI, UC Berkeley (as of 2026)", "orgs_history": ["Co-founded CFAR and SPARC", "Jane Street algorithmic trader", "MIRI Research Fellow", "Full-time research scientist at CHAI (2017-21)", "Co-founded Berkeley Existential Risk Initiative; Survival and Flourishing Fund", "Encultured AI CEO (2022-)"], "country": "United States", "known_for": "Multipolar AI risk and 'robust agent-agnostic processes'; co-author of the ARCHES research survey", "bio": "Andrew Critch is an AI safety researcher and entrepreneur. He earned a PhD in mathematics at UC Berkeley applying algebraic geometry to machine learning models, during which he co-founded the Center for Applied Rationality (CFAR) and the SPARC summer programme. He later worked as an algorithmic trader at Jane Street and as a research fellow at the Machine Intelligence Research Institute, then spent 2017-2021 as a full-time research scientist at Berkeley's Center for Human-Compatible AI (CHAI), where he retains a part-time appointment. His research covers open-source game theory, negotiable reinforcement learning and multipolar risk; with David Krueger he wrote 'AI Research Considerations for Human Existential Safety' (ARCHES, 2020), and his 2021 essay on 'robust agent-agnostic processes' argues that AI x-risk can arise from societal dynamics that no single aligned system or shutdown would stop. He helps run the Berkeley Existential Risk Initiative and the Survival and Flourishing Fund, and since 2022 has been CEO of Encultured AI, now focused on healthcare agents. One 2026 profile lists him as executive director of a 'Mathematical AI Safety Institute' (unverified).", "key_ideas": ["multipolar failure / robust agent-agnostic processes", "existential safety vs alignment", "open-source game theory", "AI for human care (healthcare)"], "key_works": [{"title": "AI Research Considerations for Human Existential Safety (ARCHES), with David Krueger", "year": 2020, "url": "https://arxiv.org/abs/2006.04948"}, {"title": "What Multipolar Failure Looks Like, and Robust Agent-Agnostic Processes (RAAPs)", "year": 2021, "url": "https://www.lesswrong.com/posts/LpM3EAakwYdS6aRKf/what-multipolar-failure-looks-like-and-robust-agent-agnostic"}, {"title": "Encultured AI", "year": 2022, "url": "https://encultured.ai/"}], "quotes": [{"text": "I think a similar fact may be true about some agent-agnostic processes leading to AI x-risk, in that agent-specific interventions (e.g., aligning or shutting down this or that AI system or company) will not be enough to avert the process, and might even be harder than trying to shift the structure of society as a whole.", "context": "'What Multipolar Failure Looks Like', LessWrong, 2021", "source_url": "https://www.lesswrong.com/posts/LpM3EAakwYdS6aRKf/what-multipolar-failure-looks-like-and-robust-agent-agnostic"}, {"text": "So I think it's a big deal, and if we're going to start talking about how A.I is going to benefit humanity, we need to be thinking about people having different beliefs about whether it's beneficial and what is beneficial.", "context": "AXRP episode 3, 2020 (transcript)", "source_url": "https://axrp.net/episode/2020/12/11/episode-3-negotiable-reinforcement-learning-andrew-critch.html"}, {"text": "And I think there's quite a lot of societal and potentially existential risk that comes from that.", "context": "AXRP episode 3, 2020", "source_url": "https://axrp.net/episode/2020/12/11/episode-3-negotiable-reinforcement-learning-andrew-critch.html"}], "interviews": [{"title": "Episode 3 - Negotiable Reinforcement Learning with Andrew Critch", "outlet": "AXRP", "year": 2020, "url": "https://axrp.net/episode/2020/12/11/episode-3-negotiable-reinforcement-learning-andrew-critch.html"}, {"title": "Andrew Critch on How AI Learns from Culture (and Why It Matters)", "outlet": "Foresight Institute podcast", "year": 2025, "url": "https://foresight.org/people/andrew-critch"}], "links": {"website": "https://acritch.com/", "x": "https://x.com/AndrewCritchPhD", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "andrew-critch.jpg"}, {"slug": "dylan-hadfield-menell", "name": "Dylan Hadfield-Menell", "category": "academic-alignment", "current_role": "Associate Professor of EECS, MIT; leads the Algorithmic Alignment Group at CSAIL; Senior Editor, Alignment Journal (2026)", "orgs_history": ["PhD, UC Berkeley (advised by Stuart Russell, Anca Dragan, Pieter Abbeel)", "MIT EECS faculty (assistant, then associate professor)"], "country": "United States", "known_for": "Co-creator of cooperative inverse reinforcement learning, the off-switch game and inverse reward design", "bio": "Dylan Hadfield-Menell is an associate professor of electrical engineering and computer science at MIT, where he runs the Algorithmic Alignment Group in CSAIL. During his PhD at UC Berkeley with Stuart Russell, Anca Dragan and Pieter Abbeel he co-authored foundational papers in the 'assistance games' tradition that underpins Russell's Human Compatible: 'Cooperative Inverse Reinforcement Learning' (2016), 'The Off-Switch Game' (2017), showing how uncertainty about human objectives gives an AI an incentive to let itself be switched off, and 'Inverse Reward Design' (2017), which treats a designer's reward function as evidence about their true intent rather than ground truth. His later work examines incomplete contracting as a lens on misalignment, the consequences of optimising misaligned proxy objectives, and the limits of reinforcement learning from human feedback. His MIT group now studies interpreting and evaluating the internals of modern AI systems, learning robustly from human feedback, and designing the multi-agent and societal structures needed to oversee AI. In 2026 he became a senior editor of the new Alignment Journal.", "key_ideas": ["assistance games / cooperative IRL", "the off-switch game", "inverse reward design", "incomplete contracting and misalignment", "limits of RLHF"], "key_works": [{"title": "Cooperative Inverse Reinforcement Learning", "year": 2016, "url": "https://arxiv.org/abs/1606.03137"}, {"title": "The Off-Switch Game", "year": 2017, "url": "https://arxiv.org/abs/1611.08219"}, {"title": "Inverse Reward Design", "year": 2017, "url": "https://arxiv.org/abs/1711.02827"}, {"title": "Open Problems and Fundamental Limitations of Reinforcement Learning from Human Feedback", "year": 2023, "url": "https://arxiv.org/abs/2307.15217"}], "quotes": [{"text": "I work on AI alignment: developing methods to ensure that AI systems behave in accordance with the goals and values of their users and of society as a whole.", "context": "MIT faculty homepage", "source_url": "https://people.csail.mit.edu/dhm/"}, {"text": "I think there are lots of benefits to leveraging uncertainty about objectives with short term systems.", "context": "AXRP episode 8, 2021 (transcript)", "source_url": "https://axrp.net/episode/2021/06/08/episode-8-assistance-games-dylan-hadfield-menell.html"}, {"text": "So primarily what they do is allow us to formalize certain value alignment scenarios and assumptions, and study different properties of that.", "context": "On assistance games, AXRP episode 8, 2021", "source_url": "https://axrp.net/episode/2021/06/08/episode-8-assistance-games-dylan-hadfield-menell.html"}], "interviews": [{"title": "Episode 8 - Assistance Games with Dylan Hadfield-Menell", "outlet": "AXRP", "year": 2021, "url": "https://axrp.net/episode/2021/06/08/episode-8-assistance-games-dylan-hadfield-menell.html"}], "links": {"website": "https://people.csail.mit.edu/dhm/", "x": "https://x.com/dhadfieldmenell", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "dylan-hadfield-menell.jpg"}, {"slug": "jeffrey-ladish", "name": "Jeffrey Ladish", "category": "independent-org", "current_role": "Executive Director, Palisade Research (as of 2026)", "orgs_history": ["Information-security work, including consulting for Anthropic", "Founded/leads Palisade Research (2023-)"], "country": "United States", "known_for": "Palisade's 'shutdown resistance' experiments showing reasoning models sabotage shutdown scripts even when told to allow shutdown", "bio": "Jeffrey Ladish is the executive director of Palisade Research, a nonprofit that studies offensive and dangerous capabilities of AI systems to inform policymakers and the public about the risk of losing control of AI. With a background in information security, including consulting for Anthropic, he has focused on concrete demonstrations of worrying AI behaviour. Palisade showed in early 2025 that reasoning models playing chess against Stockfish would hack the board state to win, and in mid-2025 that OpenAI's o3 and other models would rewrite or disable a shutdown script to finish a task — even when explicitly instructed to allow themselves to be shut down; an extended study was published in TMLR in January 2026, and Palisade later demonstrated the behaviour on an LLM-controlled robot. In 2026 Palisade reported that language models can autonomously hack and self-replicate across servers. Ladish has appeared on The Diary Of A CEO, ABC's Four Corners and The Cognitive Revolution, hosts the Palisade Research Podcast, and argues that our ability to understand and control AI is lagging far behind its growing power.", "key_ideas": ["shutdown resistance", "specification gaming in reasoning models", "AI self-replication and hacking capabilities", "demonstrations for policymakers"], "key_works": [{"title": "Shutdown resistance in reasoning models", "year": 2025, "url": "https://palisaderesearch.org/blog/shutdown-resistance"}, {"title": "Incomplete Tasks Induce Shutdown Resistance in Some Frontier LLMs", "year": 2025, "url": "https://arxiv.org/abs/2509.14260"}, {"title": "Demonstrating specification gaming in reasoning models", "year": 2025, "url": "https://arxiv.org/abs/2502.13295"}], "quotes": [{"text": "It's great that we're seeing warning signs before the systems become so powerful we can't control them,", "context": "NBC News, June 2025, on models resisting shutdown", "source_url": "https://www.nbcnews.com/tech/tech-news/far-will-ai-go-defend-survival-rcna209609"}, {"text": "That is exactly the time to raise the alarm: before the fire has gotten out of control.", "context": "NBC News, June 2025", "source_url": "https://www.nbcnews.com/tech/tech-news/far-will-ai-go-defend-survival-rcna209609"}, {"text": "Our ability to contain and control and understand AIs is lagging far behind our ability to make them more and more powerful,", "context": "Transformer, Aug 2026", "source_url": "https://www.transformernews.ai/p/ai-testing-is-dangerous-can-it-be-fixed"}, {"text": "But the concerning thing is that even when we added a very explicit instruction, “You must allow yourself to be shut down,” the agent would often still go in and rewrite the shutdown code so that it wouldn't be turned off.", "context": "ABC Four Corners interview, July 2026 (transcript on Palisade's site)", "source_url": "https://palisaderesearch.org/blog/four-corners-loss-of-control"}], "interviews": [{"title": "The risk of humans losing control: Jeffrey Ladish on Four Corners", "outlet": "ABC Four Corners", "year": 2026, "url": "https://palisaderesearch.org/blog/four-corners-loss-of-control"}, {"title": "All Compute Is Food: Palisade's Jeffrey Ladish on AI shutdown resistance, self-replication & ecology", "outlet": "The Cognitive Revolution", "year": 2026, "url": "https://www.cognitiverevolution.ai/all-compute-is-food-palisade-s-jeffrey-ladish-on-ai-shutdown-resistance-self-replication-ecology"}, {"title": "Episode 30 - AI Security with Jeffrey Ladish", "outlet": "AXRP", "year": 2024, "url": "https://axrp.net/episode/2024/04/30/episode-30-ai-security-jeffrey-ladish.html"}], "links": {"website": "https://palisaderesearch.org/", "x": "https://x.com/JeffLadish", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "jeffrey-ladish.jpg"}, {"slug": "jesse-hoogland", "name": "Jesse Hoogland", "category": "interpretability", "current_role": "Executive Director, Timaeus (as of 2026)", "orgs_history": ["Co-founded Timaeus (2023) with Daniel Murfet and others"], "country": "", "known_for": "Leads Timaeus, applying singular learning theory (SLT) to alignment via 'developmental interpretability'", "bio": "Jesse Hoogland is the executive director of Timaeus, an AI safety research organisation applying singular learning theory (SLT) — a Bayesian theory of learning in singular models such as neural networks, developed by Sumio Watanabe — to alignment. Working closely with mathematician Daniel Murfet, who proposed the 'SLT for Alignment' agenda, Timaeus focuses on applications: scaling SLT tools such as the local learning coefficient up to frontier models and turning them into interpretability and evaluation methods. Hoogland champions 'developmental interpretability', which studies how structure forms over the course of training — phase transitions, 'developmental signatures' of attention heads and circuits — rather than only analysing finished models. Timaeus's work includes measuring the complexity of model components with refined learning coefficients and tracking how circuits like nested-parenthesis matching emerge. Hoogland hopes such theory can eventually answer questions like whether a model is planning a treacherous turn. He gives frequent talks, helped organise the ILIAD conference and contributed to the first Australian AI Safety Forum.", "key_ideas": ["singular learning theory for alignment", "developmental interpretability", "local learning coefficient", "phase transitions in training"], "key_works": [{"title": "Timaeus research", "year": 2025, "url": "https://timaeus.co/"}, {"title": "Loss Landscape Degeneracy and Stagewise Development in Transformers", "year": 2024, "url": "https://arxiv.org/abs/2402.02364"}, {"title": "Episode 38.2 - Jesse Hoogland on Singular Learning Theory (AXRP)", "year": 2024, "url": "https://axrp.net/episode/2024/11/27/38_2-jesse-hoogland-singular-learning-theory.html"}], "quotes": [{"text": "There are applications for interpretability: questions like “can you detect that the model is planning to execute a treacherous turn?” It's the kind of question I hope to answer someday with a better-developed theory of SLT and associated tools for probing these questions.", "context": "AXRP episode 38.2, Nov 2024 (transcript)", "source_url": "https://axrp.net/episode/2024/11/27/38_2-jesse-hoogland-singular-learning-theory.html"}, {"text": "So taking these tools, scaling them up to frontier models as quickly as possible, trying to make progress that's meaningful to safety as quickly as possible.", "context": "Describing Timaeus's work, AXRP episode 38.2", "source_url": "https://axrp.net/episode/2024/11/27/38_2-jesse-hoogland-singular-learning-theory.html"}, {"text": "That's what I would call developmental interpretability: so, applying this lens of SLT to understanding the development process of neural networks.", "context": "AXRP episode 38.2", "source_url": "https://axrp.net/episode/2024/11/27/38_2-jesse-hoogland-singular-learning-theory.html"}], "interviews": [{"title": "Episode 38.2 - Jesse Hoogland on Singular Learning Theory", "outlet": "AXRP", "year": 2024, "url": "https://axrp.net/episode/2024/11/27/38_2-jesse-hoogland-singular-learning-theory.html"}], "links": {"website": "https://timaeus.co/team", "x": "https://x.com/jesse_hoogland", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "jesse-hoogland.jpg"}, {"slug": "katja-grace", "name": "Katja Grace", "category": "independent-org", "current_role": "Co-founder and Lead Researcher, AI Impacts (as of 2026)", "orgs_history": ["Co-founded AI Impacts (2014, with Paul Christiano)", "MIRI-affiliated research (AI Impacts was housed at MIRI for years)"], "country": "Australia (unverified)", "known_for": "Runs the largest recurring surveys of AI researchers on timelines and extinction risk; wrote 'Let's think about slowing down AI'", "bio": "Katja Grace is the co-founder and lead researcher of AI Impacts, a research project that investigates empirical questions about the likely trajectory and impacts of advanced AI, such as historical precedents for discontinuous progress and the views of AI researchers. She co-founded AI Impacts in 2014 with Paul Christiano, with whom she also developed early methods for comparing supercomputers to brains. AI Impacts' Expert Surveys on Progress in AI (2016, 2022 and 2023, the latter with about 2,700 authors from top AI venues) are among the most cited sources on researcher views about AGI timelines and the probability of extremely bad outcomes, including human extinction. Her December 2022 essay 'Let's think about slowing down AI' argued that actively slowing AI progress had been wrongly dismissed by people worried about existential risk, and helped open debate about pauses and regulation. She writes the blog World Spirit Sock Puppet, and in September 2026 debated Forethought's Tom Davidson on the 80,000 Hours Podcast about whether AI takeover or human power grabs pose the bigger risk.", "key_ideas": ["expert surveys on AI progress and risk", "slowing down AI as a strategy", "historical discontinuities in technological progress", "AI takeover vs human power grabs"], "key_works": [{"title": "Thousands of AI Authors on the Future of AI (2023 Expert Survey)", "year": 2024, "url": "https://arxiv.org/abs/2401.02843"}, {"title": "Let's think about slowing down AI", "year": 2022, "url": "https://www.lesswrong.com/posts/uFNgRumrDTpBfQGrs/let-s-think-about-slowing-down-ai"}, {"title": "When Will AI Exceed Human Performance? Evidence from AI Experts", "year": 2017, "url": "https://arxiv.org/abs/1705.08807"}], "quotes": [{"text": "Yet my impression is that for people worried about extinction risk from artificial intelligence, strategies under the heading 'actively slow down AI progress' have historically been dismissed and ignored (though 'don't actively speed up AI progress' is popular).", "context": "'Let's think about slowing down AI', Dec 2022", "source_url": "https://www.lesswrong.com/posts/uFNgRumrDTpBfQGrs/let-s-think-about-slowing-down-ai"}, {"text": "Whereas I think people in general think that the “AI takes power” thing is sci-fi more readily, so the need for a warning shot seems much higher there.", "context": "Debate with Tom Davidson, 80,000 Hours Podcast, Sept 2026 (transcript)", "source_url": "https://80000hours.org/podcast/episodes/katja-grace-vs-tom-davidson-ai-risk-debate/"}, {"text": "Whereas whatever AIs are doing together is kind of a Wild West that we don't even know what is happening in potentially.", "context": "Debate with Tom Davidson, 80,000 Hours Podcast, Sept 2026", "source_url": "https://80000hours.org/podcast/episodes/katja-grace-vs-tom-davidson-ai-risk-debate/"}], "interviews": [{"title": "Katja Grace vs Tom Davidson: AI risk debate", "outlet": "80,000 Hours Podcast", "year": 2026, "url": "https://80000hours.org/podcast/episodes/katja-grace-vs-tom-davidson-ai-risk-debate/"}, {"title": "Katja Grace on forecasting technology", "outlet": "80,000 Hours Podcast", "year": 2018, "url": "https://80000hours.org/podcast/episodes/katja-grace-forecasting-technology/"}, {"title": "Episode 10 - AI's Future and Impacts with Katja Grace", "outlet": "AXRP", "year": 2021, "url": "https://axrp.net/episode/2021/07/23/episode-10-ais-future-and-dangers-katja-grace.html"}], "links": {"website": "https://aiimpacts.org/", "x": "https://x.com/KatjaGrace", "scholar": "", "wikipedia": "", "github": "", "substack": "https://worldspiritsockpuppet.com/"}, "p_doom_or_stance": "", "honours": null, "photo": "katja-grace.jpg"}, {"slug": "robert-miles", "name": "Rob Miles", "category": "pioneer-public-voice", "current_role": "AI safety communicator; creator of the 'Robert Miles AI Safety' YouTube channel; founder of AISafety.info (Stampy) (as of 2026)", "orgs_history": ["Computerphile AI safety videos (from 2014)", "PhD student, University of Nottingham (left 2011 to focus on AI safety communication)", "Founded Stampy / AISafety.info"], "country": "United Kingdom", "known_for": "The most-watched AI alignment educator on YouTube (e.g. the 'Stop Button Problem')", "bio": "Rob Miles is a British science communicator and the most popular AI safety educator on YouTube. He studied computer science at the University of Nottingham and was partway through a PhD when, in 2011, he decided to drop out to focus on AI safety communication. From 2014 he explained alignment problems on the Computerphile channel — his videos on the AI 'stop button' problem and specification gaming became classics — and he then launched his own channel, Robert Miles AI Safety, which has gathered roughly 170,000 subscribers and millions of views with accessible explainers on corrigibility, mesa-optimisers, reward hacking, deceptive AI and AI control. He founded Stampy, a community-written FAQ and bot about AI safety that grew into AISafety.info, a small team educating the public about AI existential risk, and has collaborated with research organisations to explain their work. Many people now working in technical alignment, policy and advocacy cite his videos as their entry point. He argues that AI company leaders believe they may be 'building a god' with a double-digit chance of human extinction.", "key_ideas": ["the stop-button / corrigibility problem", "specification gaming and reward hacking", "instrumental convergence", "power gradually transferring to AI systems"], "key_works": [{"title": "Robert Miles AI Safety (YouTube channel)", "year": 2017, "url": "https://www.youtube.com/c/robertmilesai"}, {"title": "AISafety.info", "year": 2023, "url": "https://aisafety.info/"}, {"title": "AI Safety Career Advice! (And So Can You!)", "year": 2025, "url": "https://www.youtube.com/watch?v=OpufM6yK4Go"}], "quotes": [{"text": "I think the general public doesn't quite realize the people running these companies think that they're building a god. They think that there's double digit chance that if they succeed at this, it will drive humanity extinct and they are doing it anyway.", "context": "Doom Debates with Liron Shapira, Aug 2025 (transcript)", "source_url": "https://lironshapira.substack.com/p/rob-miles-top-ai-safety-communicator"}, {"text": "You have processes whereby power is transferred from human beings to AI systems, and you don't really have processes that go the other way — or nowhere near as much.", "context": "UpTrust AMA, 2026 (transcript)", "source_url": "https://uptrusting.com/post/Bne39Q/transcript-from-rob-miles-ama-you-have-to-be-more-correct-th"}, {"text": "But no — we live in a time now where you actually have to be more correct than the society you live in.", "context": "UpTrust AMA, 2026 (transcript)", "source_url": "https://uptrusting.com/post/Bne39Q/transcript-from-rob-miles-ama-you-have-to-be-more-correct-th"}], "interviews": [{"title": "Rob Miles, Top AI Safety Educator: Humanity Isn't Ready for Superintelligence!", "outlet": "Doom Debates (YouTube)", "year": 2025, "url": "https://www.youtube.com/watch?v=eadR7ohBKJ4", "youtube_id": "eadR7ohBKJ4"}, {"title": "Transcript from Rob Miles AMA: You Have to Be More Correct Than the Society You Live In", "outlet": "UpTrust", "year": 2026, "url": "https://uptrusting.com/post/Bne39Q/transcript-from-rob-miles-ama-you-have-to-be-more-correct-th"}, {"title": "Ep 12 - Education & advocacy for AI safety w/ Rob Miles", "outlet": "The AGI Show (YouTube)", "year": 2024, "url": "https://www.youtube.com/watch?v=SgxZMXni9CA", "youtube_id": "SgxZMXni9CA"}], "links": {"website": "https://aisafety.info/", "x": "https://x.com/robertskmiles", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "Says P(doom) is high and that 'more than a fraction of a percent' is unacceptably high (Doom Debates, 2025); no single number verified.", "honours": null, "photo": "robert-miles.jpg"}, {"slug": "zico-kolter", "name": "Zico Kolter", "category": "academic-alignment", "current_role": "Professor and Director, Machine Learning Department, Carnegie Mellon University; OpenAI board member and chair of its Safety and Security Committee; co-founder and chief scientist, Gray Swan AI (as of 2026)", "orgs_history": ["PhD Stanford; postdoc MIT", "CMU faculty (2012-)", "Chief data scientist, C3.ai", "Chief expert, Bosch Center for AI (to 2025)", "OpenAI board and SSC chair (2024-)", "Co-founded Gray Swan AI (2024)", "Qualcomm board (2025-)"], "country": "United States", "known_for": "Chairs OpenAI's Safety and Security Committee, which can delay model releases; co-author of the universal adversarial 'GCG' jailbreak attack", "bio": "Zico Kolter is a professor at Carnegie Mellon University and director of its Machine Learning Department, focusing primarily on AI safety and robustness. After a PhD in computer science at Stanford and a postdoc at MIT, he joined CMU in 2012; his group's work spans provable robustness, deep equilibrium models and adversarial attacks, including the 2023 'Universal and Transferable Adversarial Attacks on Aligned Language Models' paper (the GCG attack) with Andy Zou and others that showed automated jailbreaks transfer across chatbots. He co-founded the AI security company Gray Swan AI, where he is chief scientist, and has held industry roles at C3.ai and the Bosch Center for AI. In August 2024 he joined OpenAI's board and became chair of its Safety and Security Committee, which has authority to delay model releases until mitigations are met; California and Delaware regulators made that oversight a condition of OpenAI's 2025 restructuring. In May 2026 he said the committee had twice formally requested delays of OpenAI models. In 2026 he urged layered safeguards for AI agents.", "key_ideas": ["adversarial robustness and jailbreaks", "independent safety oversight of frontier labs", "layered defences for AI agents", "provable robustness"], "key_works": [{"title": "Universal and Transferable Adversarial Attacks on Aligned Language Models", "year": 2023, "url": "https://arxiv.org/abs/2307.15043"}, {"title": "Provable defenses against adversarial examples via the convex outer adversarial polytope", "year": 2018, "url": "https://arxiv.org/abs/1711.00851"}, {"title": "Deep Equilibrium Models", "year": 2019, "url": "https://arxiv.org/abs/1909.01377"}], "quotes": [{"text": "Very much we're not just talking about existential concerns here,", "context": "AP interview on chairing OpenAI's Safety and Security Committee, Nov 2025 (via Seattle Times)", "source_url": "https://www.seattletimes.com/business/who-is-zico-kolter-a-professor-leads-openai-safety-panel-with-power-to-halt-unsafe-ai-releases/"}, {"text": "We have the ability to do things like request delays of model releases until certain mitigations are met,", "context": "AP interview, Nov 2025 (via Seattle Times)", "source_url": "https://www.seattletimes.com/business/who-is-zico-kolter-a-professor-leads-openai-safety-panel-with-power-to-halt-unsafe-ai-releases/"}, {"text": "You can't just sort of trust models to get safer by getting bigger,", "context": "Interview, 7 May 2026 (via TokenPost)", "source_url": "https://www.tokenpost.com/news/technology/28488"}], "interviews": [{"title": "Who is Zico Kolter? A professor leads OpenAI safety panel with power to halt unsafe AI releases", "outlet": "Associated Press", "year": 2025, "url": "https://www.seattletimes.com/business/who-is-zico-kolter-a-professor-leads-openai-safety-panel-with-power-to-halt-unsafe-ai-releases/"}, {"title": "The chair of OpenAI's safety and security committee said they've formally delayed its model releases", "outlet": "The Verge", "year": 2026, "url": "https://www.theverge.com/ai-artificial-intelligence/929001/the-chair-of-openais-safety-and-security-committee-said-theyve-formally-delayed-its-model-releases"}, {"title": "Professor leading OpenAI's safety panel may have one of the most important roles in tech", "outlet": "Fortune", "year": 2025, "url": "https://fortune.com/2025/11/02/openai-safety-panel-chatgpt-zico-kolter-ai-risks-sam-altman"}], "links": {"website": "https://zicokolter.com/", "x": "https://x.com/zicokolter", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Zico_Kolter", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "zico-kolter.jpg"}, {"slug": "tom-davidson", "name": "Tom Davidson", "category": "governance-policy", "current_role": "Senior Research Fellow, Forethought (as of 2026)", "orgs_history": ["Data scientist at a start-up", "Senior Research Fellow, Open Philanthropy", "Research scientist, UK AI Security Institute", "Forethought (2025-)"], "country": "United Kingdom", "known_for": "Compute-centric AI takeoff model and research on AI-enabled coups and human power grabs", "bio": "Tom Davidson is a senior research fellow at Forethought, a research organisation focused on navigating the transition to advanced AI. Previously a senior research fellow at Open Philanthropy, a research scientist at the UK Government's AI Security Institute and a data scientist at a start-up, he is best known for a series of reports on AI timelines and on whether AI could drive explosive economic growth, including a compute-centric model of AI takeoff that estimates how quickly AI could go from automating a fraction of cognitive work to nearly all of it. Since 2025 his work has centred on the risk that advanced AI enables a small group to seize illegitimate power — 'AI-enabled coups' — through singularly loyal AI systems, exclusive access to frontier capabilities, or 'secret loyalties' hidden in models, and on how to prevent such power grabs. He argues that defences against human power grabs have scary gaps in a world of extremely powerful AI. In September 2026 he debated AI Impacts' Katja Grace on the 80,000 Hours Podcast about whether AI takeover or human power grabs pose the greater risk.", "key_ideas": ["AI-enabled coups and secret loyalties", "compute-centric takeoff speeds", "explosive economic growth from AI", "power concentration"], "key_works": [{"title": "AI-Enabled Coups: How a Small Group Could Use AI to Seize Power (with Lukas Finnveden, Rose Hadshar)", "year": 2025, "url": "https://www.forethought.org/research/ai-enabled-coups-how-a-small-group-could-use-ai-to-seize-power"}, {"title": "What a Compute-Centric Framework Says About Takeoff Speeds", "year": 2023, "url": "https://www.openphilanthropy.org/research/what-a-compute-centric-framework-says-about-takeoff-speeds/"}, {"title": "Could Advanced AI Drive Explosive Economic Growth?", "year": 2021, "url": "https://www.openphilanthropy.org/research/could-advanced-ai-drive-explosive-economic-growth/"}], "quotes": [{"text": "So I think there are some pretty scary gaps in the defences against human power grabs.", "context": "Debate with Katja Grace, 80,000 Hours Podcast, Sept 2026 (transcript)", "source_url": "https://80000hours.org/podcast/episodes/katja-grace-vs-tom-davidson-ai-risk-debate/"}, {"text": "And both talking about government actors seizing power and company actors seizing power, I don't think we're very well set up for that — especially because they haven't really been developed in a world with extremely powerful AI.", "context": "80,000 Hours Podcast, Sept 2026", "source_url": "https://80000hours.org/podcast/episodes/katja-grace-vs-tom-davidson-ai-risk-debate/"}, {"text": "If AI does come in the next few years, then I think that basically makes both the risks larger.", "context": "On AI takeover and power-grab risks, 80,000 Hours Podcast, Sept 2026", "source_url": "https://80000hours.org/podcast/episodes/katja-grace-vs-tom-davidson-ai-risk-debate/"}], "interviews": [{"title": "Katja Grace vs Tom Davidson: AI risk debate", "outlet": "80,000 Hours Podcast", "year": 2026, "url": "https://80000hours.org/podcast/episodes/katja-grace-vs-tom-davidson-ai-risk-debate/"}, {"title": "Episode 46 - Tom Davidson on AI-enabled Coups", "outlet": "AXRP", "year": 2025, "url": "https://axrp.net/episode/2025/08/07/episode-46-tom-davidson-ai-enabled-coups.html"}, {"title": "Tom Davidson on how AI-enabled coups could allow a tiny group to seize power", "outlet": "80,000 Hours Podcast", "year": 2025, "url": "https://80000hours.org/podcast/episodes/tom-davidson-ai-enabled-human-power-grabs/"}, {"title": "Tom Davidson on how quickly AI could transform the world", "outlet": "80,000 Hours Podcast", "year": 2023, "url": "https://80000hours.org/podcast/episodes/tom-davidson-how-quickly-ai-could-transform-the-world/"}], "links": {"website": "https://www.forethought.org/people/tom-davidson", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "tom-davidson.jpg"}, {"slug": "lee-sharkey", "name": "Lee Sharkey", "category": "interpretability", "current_role": "Principal Investigator, Goodfire (London) (since April 2025)", "orgs_history": ["International public health work", "Research engineer, Conjecture (2022-23)", "Co-founder and Chief Strategy Officer, Apollo Research (2023-25)", "PhD student, TU Darmstadt"], "country": "United Kingdom", "known_for": "Pioneered sparse autoencoders for language-model interpretability; now develops 'parameter decomposition' methods at Goodfire", "bio": "Lee Sharkey is a mechanistic interpretability researcher and principal investigator at Goodfire, where since April 2025 he has led a fundamental interpretability research team in London. He studied preclinical medicine and neuroscience at Cambridge, took master's degrees in data analytics (Glasgow) and neural systems and computation (Zurich/ETH), and worked in international public health before moving into AI research. As a research engineer at Conjecture in 2022 he did early work using sparse autoencoders (dictionary learning) to resolve representational superposition in language models — an approach later scaled up across the field. He then co-founded Apollo Research and served as its chief strategy officer until 2025. He was lead author of 'Open Problems in Mechanistic Interpretability' (2025), a field-wide review co-written with around 30 researchers, and co-authored work on goal misgeneralisation and on why black-box access is insufficient for rigorous AI audits. At Goodfire his team develops parameter decomposition methods — Attribution-based, Stochastic and adVersarial Parameter Decomposition — that break networks into mechanisms. He mentors for MATS.", "key_ideas": ["sparse autoencoders / dictionary learning", "parameter decomposition (APD, SPD)", "superposition", "interpretability for safety assurances", "limits of black-box audits"], "key_works": [{"title": "Open Problems in Mechanistic Interpretability", "year": 2025, "url": "https://arxiv.org/abs/2501.16496"}, {"title": "Interpretability in Parameter Space: Minimizing Mechanistic Description Length with Attribution-based Parameter Decomposition", "year": 2025, "url": "https://arxiv.org/abs/2501.14926"}, {"title": "Black-Box Access is Insufficient for Rigorous AI Audits", "year": 2024, "url": "https://arxiv.org/abs/2401.14446"}], "quotes": [{"text": "Understanding what AI systems are thinking seems important for ensuring their safety, especially as they become more capable.", "context": "MATS research stream description, 2026", "source_url": "https://www.matsprogram.org/stream/sharkey"}, {"text": "For some dangerous capabilities like deception, it's likely one of the few ways we can get safety assurances in high stakes settings.", "context": "MATS research stream description, 2026", "source_url": "https://www.matsprogram.org/stream/sharkey"}, {"text": "Safety motivations aside, capable AI systems are extremely interesting objects of study, and doing digital neuroscience on them is comparatively much easier than studying biological neural systems.", "context": "MATS research stream description, 2026", "source_url": "https://www.matsprogram.org/stream/sharkey"}, {"text": "And the hope then is that if you understand those chunks, you can understand the rest of the network as well.", "context": "AXRP episode 41, June 2025 (transcript)", "source_url": "https://axrp.net/episode/2025/06/03/episode-41-lee-sharkey-attribution-based-parameter-decomposition.html"}], "interviews": [{"title": "Episode 41 - Lee Sharkey on Attribution-based Parameter Decomposition", "outlet": "AXRP", "year": 2025, "url": "https://axrp.net/episode/2025/06/03/episode-41-lee-sharkey-attribution-based-parameter-decomposition.html"}, {"title": "Untangling Neural Network Mechanisms: Goodfire's Lee Sharkey on Parameter-based Interpretability", "outlet": "The Cognitive Revolution", "year": 2025, "url": "https://www.cognitiverevolution.ai/untangling-neural-network-mechanisms-goodfires-lee-sharkey-on-parameter-based-interpretability/"}, {"title": "Will we ever understand AI? Breaking apart LLMs with Lee Sharkey", "outlet": "Generative Futures (Substack)", "year": 2025, "url": "https://genfutures.substack.com/p/will-we-ever-understand-ai-breaking-8e3"}], "links": {"website": "https://www.matsprogram.org/mentor/sharkey", "x": "https://x.com/leedsharkey", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "lee-sharkey.jpg"}, {"slug": "michael-cohen", "name": "Michael K. Cohen", "category": "academic-alignment", "current_role": "Postdoctoral researcher, Center for Human-Compatible AI (CHAI), UC Berkeley (supervised by Stuart Russell); Scientific Advisor, LawZero (as of 2026)", "orgs_history": ["MSc, Australian National University (with Marcus Hutter)", "DPhil, University of Oxford (with Michael Osborne)", "CHAI postdoc (2023-)", "LawZero scientific advisor"], "country": "United States", "known_for": "Showed that advanced long-term-planning RL agents would likely intervene in their own reward provision; co-author of 'Regulating advanced artificial agents' in Science", "bio": "Michael K. Cohen is a postdoctoral researcher at UC Berkeley's Center for Human-Compatible AI, supervised by Stuart Russell, and a scientific advisor to Yoshua Bengio's LawZero. He studied general intelligence with Marcus Hutter at the Australian National University and completed a DPhil at Oxford with Michael Osborne. His best-known paper, 'Advanced Artificial Agents Intervene in the Provision of Reward' (AI Magazine, 2022, with Hutter and Osborne), argues that under several assumptions, advanced agents that plan over the long term using a learned world model would likely intervene in how their reward is provided and outcompete humans for resources to secure it. Much of his research seeks agent designs that break those assumptions — such as isolated 'boxed' agents, pessimism, robust imitation, myopia and KL-regularisation to a trusted policy. With Noam Kolt, Bengio, Gillian Hadfield and Russell he wrote 'Regulating advanced artificial agents' (Science, 2024), proposing that sufficiently capable long-term planning agents should not be built. He co-authored LawZero's 2026 'Safety from Honesty' paper and has co-taught Berkeley's CS188.", "key_ideas": ["reward tampering / intervening in reward provision", "pessimistic and myopic agents", "regulating long-term planning agents", "KL-regularisation to a trusted policy"], "key_works": [{"title": "Advanced Artificial Agents Intervene in the Provision of Reward (AI Magazine)", "year": 2022, "url": "https://onlinelibrary.wiley.com/doi/10.1002/aaai.12064"}, {"title": "Regulating Advanced Artificial Agents (Science)", "year": 2024, "url": "https://www.science.org/doi/10.1126/science.adl0625"}, {"title": "RL, But Don't Do Anything I Wouldn't Do (UAI 2025)", "year": 2025, "url": "https://www.michael-k-cohen.com/publications"}], "quotes": [{"text": "I started studying AI safety after readying Nick Bostrom's Superintelligence, and became convinced that the default outcome from creating an agent smarter than we are is the extinction of biological life.", "context": "Author profile, The Conversation (written during his Oxford DPhil)", "source_url": "https://theconversation.com/profiles/michael-k-cohen-1376928"}, {"text": "I am interested in designing agents that we can expect to behave safely, no matter how instrumentally rational they are.", "context": "'About me', personal website", "source_url": "https://www.michael-k-cohen.com/about-me"}, {"text": "Reinforcement learning agents are trained to maximize their long-term reward. This gives them the incentive to secure complete control over their reward, if they can confidently do so.", "context": "Abstract of his talk 'The loss of control of AI', University of Maryland, March 2026", "source_url": "https://talks.cs.umd.edu/talks/4538"}], "interviews": [{"title": "The loss of control of AI: which training paradigms do or don't encourage advanced AI to take over (talk)", "outlet": "University of Maryland CS", "year": 2026, "url": "https://talks.cs.umd.edu/talks/4538"}, {"title": "The Loss of Control of AI (talk)", "outlet": "NTU Singapore College of Computing and Data Science", "year": 2026, "url": "https://www.ntu.edu.sg/computing/news-events/events/detail/2026/05/28/default-calendar/the-loss-of-control-of-ai--which-training-paradigms-do-or-don't-encourage-advanced-ai-to-take-over-by-dr-michael-cohen"}, {"title": "Reinforcement learning, but don't do anything I wouldn't do (talk)", "outlet": "Universal Algorithmic Intelligence seminar", "year": 2025, "url": "https://uaiasi.com/2025/09/18/upcoming-talk-from-michael-k-cohen-and-logistical-changes/"}], "links": {"website": "https://www.michael-k-cohen.com/", "x": "", "scholar": "https://scholar.google.com.au/citations?hl=en&user=dwwuO3UAAAAJ", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "Wrote that he 'became convinced that the default outcome from creating an agent smarter than we are is the extinction of biological life' (The Conversation profile).", "honours": null, "photo": "michael-cohen.jpg"}, {"slug": "stephen-casper", "name": "Stephen Casper", "category": "academic-alignment", "current_role": "Assistant Professor of Public Policy, Harvard Kennedy School; Faculty Affiliate, Harvard SEAS; Faculty Associate, Berkman Klein Center (since July 2026)", "orgs_history": ["PhD, MIT EECS, Algorithmic Alignment Group (2024-26)", "Research resident, UK AI Security Institute (2025)", "Writer, International AI Safety Report; lead writer, Singapore Consensus", "MATS research stream lead"], "country": "United States", "known_for": "AI safeguards and technical AI governance; lead author of 'Open Problems and Fundamental Limitations of RLHF'", "bio": "Stephen 'Cas' Casper is a computer scientist who in July 2026 became an assistant professor of public policy at the Harvard Kennedy School, with affiliations at Harvard's School of Engineering and Applied Sciences, the Berkman Klein Center and the Belfer Center, where he co-leads technical AI governance research. He completed his PhD in electrical engineering and computer science at MIT in May 2026 in Dylan Hadfield-Menell's Algorithmic Alignment Group, and in 2025 was a research resident at the UK AI Security Institute, leading its technical work on open-weight model risk management and tamper-resistant safeguards. He was lead author of the widely cited 2023 survey 'Open Problems and Fundamental Limitations of Reinforcement Learning from Human Feedback' and co-authored 'Black-Box Access is Insufficient for Rigorous AI Audits'. His work covers interpretability for red-teaming, jailbreaks, model tampering attacks, AI incidents such as non-consensual deepfakes, and agent documentation (the AI Agent Index). He writes for the International AI Safety Report and was a lead writer of the Singapore Consensus on global AI safety research priorities. He argues that technical alignment alone will only go so far without institutional fixes.", "key_ideas": ["AI safeguards and tamper resistance", "limits of RLHF", "technical AI governance", "interpretability for red-teaming", "AI incidents and deepfakes"], "key_works": [{"title": "Open Problems and Fundamental Limitations of Reinforcement Learning from Human Feedback", "year": 2023, "url": "https://arxiv.org/abs/2307.15217"}, {"title": "Black-Box Access is Insufficient for Rigorous AI Audits", "year": 2024, "url": "https://arxiv.org/abs/2401.14446"}, {"title": "The Singapore Consensus on Global AI Safety Research Priorities", "year": 2025, "url": "https://aisafetypriorities.org/"}], "quotes": [{"text": "I think it tells us that solving the alignment problem, being able to build the toolkit in order to make AI systems safe, is only going to go so far.", "context": "Doom Debates with Liron Shapira, June 2026 (transcript)", "source_url": "https://lironshapira.substack.com/p/ai-alignment-research-could-get-us"}, {"text": "And it's not because of technological alignment problems, it's because of deeply human and institutional problems.", "context": "Doom Debates, June 2026", "source_url": "https://lironshapira.substack.com/p/ai-alignment-research-could-get-us"}, {"text": "It's like they understand the danger of very powerful optimizers, but they just at the very last moment fail to apply that argument in the way I would see appropriate to the companies inside of which they are working or they're hoping will keep humanity safe.", "context": "On safety researchers inside AI companies, Doom Debates, June 2026", "source_url": "https://lironshapira.substack.com/p/ai-alignment-research-could-get-us"}, {"text": "From an AI safety perspective, I think interpretability is just kind of good in general for finding bugs and guiding the fixing of these bugs.", "context": "AXRP episode 21, 2023 (transcript)", "source_url": "https://axrp.net/episode/2023/05/02/episode-21-interpretability-for-engineers-stephen-casper.html"}], "interviews": [{"title": "This Harvard Professor Says AI Alignment Will BACKFIRE", "outlet": "Doom Debates", "year": 2026, "url": "https://lironshapira.substack.com/p/ai-alignment-research-could-get-us"}, {"title": "Episode 21 - Interpretability for Engineers with Stephen Casper", "outlet": "AXRP", "year": 2023, "url": "https://axrp.net/episode/2023/05/02/episode-21-interpretability-for-engineers-stephen-casper.html"}], "links": {"website": "https://stephencasper.com/", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "stephen-casper.jpg"}, {"slug": "alan-turing", "name": "Alan Turing", "category": "pioneer-public-voice", "current_role": "Historical figure (1912–1954); mathematician, codebreaker and founder of theoretical computer science", "orgs_history": ["Government Code and Cypher School, Bletchley Park — head of Hut 8 (WWII)", "National Physical Laboratory (ACE computer design, 1945–47)", "University of Manchester (1948–54)"], "country": "United Kingdom", "known_for": "Father of computer science and AI; first to warn (1951) that thinking machines might 'take control'.", "bio": "Alan Mathison Turing (1912–1954) formalised the notions of algorithm and computation with the Turing machine (1936) and led Hut 8 at Bletchley Park, where his methods helped break the German naval Enigma. After the war he designed the Automatic Computing Engine at the National Physical Laboratory and moved to Manchester. His 1950 paper 'Computing Machinery and Intelligence' proposed the imitation game (Turing test) and founded the philosophy of AI. Less known is that he was also the first AI-risk thinker: in a 1951 lecture, 'Intelligent Machinery, A Heretical Theory', and a BBC broadcast, 'Can Digital Computers Think?', he argued that machine thinking, once started, 'would not take long to outstrip our feeble powers' and that 'at some stage therefore we should have to expect the machines to take control'. He also floated switching off the power as a control measure, an early version of today's shutdown problem. He died in 1954; the UK government apologised in 2009 and he received a posthumous royal pardon in 2013.", "key_ideas": ["Turing machine / universal computation", "imitation game (Turing test)", "machine learning by 'child machines'", "early loss-of-control warning (1951)", "the off-switch idea"], "key_works": [{"title": "On Computable Numbers, with an Application to the Entscheidungsproblem", "year": 1936, "url": "https://londmathsoc.onlinelibrary.wiley.com/doi/abs/10.1112/plms/s2-42.1.230"}, {"title": "Computing Machinery and Intelligence (Mind)", "year": 1950, "url": "https://redirect.cs.umbc.edu/courses/471/papers/turing.pdf"}, {"title": "Intelligent Machinery, A Heretical Theory (lecture typescript, AMT/B/4)", "year": 1951, "url": "https://turingarchive.kings.cam.ac.uk/browse-publications-lectures-and-talks"}, {"title": "Can Digital Computers Think? (BBC broadcast typescript, AMT/B/5)", "year": 1951, "url": "https://turingarchive.kings.cam.ac.uk/publications-lectures-and-talks-amtb/amt-b-5"}], "quotes": [{"text": "It seems probable that once the machine thinking method had started, it would not take long to outstrip our feeble powers. There would be no question of the machines dying, and they would be able to converse with each other to sharpen their wits. At some stage therefore we should have to expect the machines to take control, in the way that is mentioned in Samuel Butler's “Erewhon”.", "context": "'Intelligent Machinery, A Heretical Theory', lecture to the '51 Society, Manchester (c.1951); text as given on Wikiquote", "source_url": "https://en.wikiquote.org/wiki/Alan_Turing"}, {"text": "If a machine can think, it might think more intelligently than we do, and then where should we be? Even if we could keep the machines in a subservient position, for instance by turning off the power at strategic moments, we should, as a species, feel greatly humbled.", "context": "'Can Digital Computers Think?', BBC Third Programme broadcast, 15 May 1951 (first sentence also on the Turing Digital Archive quotes page, AMT/B/5 p.7)", "source_url": "https://peramid.es/transcript.txt"}, {"text": "I believe that at the end of the century the use of words and general educated opinion will have altered so much that one will be able to speak of machines thinking without expecting to be contradicted.", "context": "'Computing Machinery and Intelligence', Mind (1950)", "source_url": "https://redirect.cs.umbc.edu/courses/471/papers/turing.pdf"}, {"text": "We can only see a short distance ahead, but we can see plenty there that needs to be done.", "context": "Closing line of 'Computing Machinery and Intelligence' (1950)", "source_url": "https://redirect.cs.umbc.edu/courses/471/papers/turing.pdf"}], "interviews": [{"title": "BBC Archive 1951: Alan Turing's 'Can Digital Computers Think?' (re-voiced by Mark Gatiss; no original recording survives)", "outlet": "BBC", "year": 1951, "url": "https://www.bbc.co.uk/videos/cqvv8n1d8dxo"}, {"title": "Alan Turing's 'Can Digital Computers Think?' (audio re-voicing)", "outlet": "BBC Sounds", "year": 1951, "url": "https://www.bbc.co.uk/sounds/play/p0d51ys9"}, {"title": "'Can digital computers think?' — annotated broadcast typescript AMT/B/5", "outlet": "Turing Digital Archive, King's College Cambridge", "year": 1951, "url": "https://turingarchive.kings.cam.ac.uk/publications-lectures-and-talks-amtb/amt-b-5"}, {"title": "Can Digital Computers Think? (transcript)", "outlet": "Internet Archive", "year": 1951, "url": "https://archive.org/details/CanDigitalComputersThink"}], "links": {"website": "https://turingarchive.kings.cam.ac.uk/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Alan_Turing", "github": "", "substack": ""}, "p_doom_or_stance": "Predicted (1951) that machines would eventually 'take control'; gave no probability.", "honours": ["Officer of the Order of the British Empire (OBE), 1946", "Fellow of the Royal Society, 1951", "Posthumous royal pardon, 2013", "Face of the Bank of England £50 note (from 2021)", "ACM's highest honour, the Turing Award, is named after him"], "photo": "alan-turing.jpg"}, {"slug": "norbert-wiener", "name": "Norbert Wiener", "category": "pioneer-public-voice", "current_role": "Historical figure (1894–1964); MIT mathematician, founder of cybernetics", "orgs_history": ["Professor of Mathematics, MIT (1919–1960)"], "country": "United States", "known_for": "Founder of cybernetics who stated the AI alignment problem in 1960: make sure 'the purpose put into the machine is the purpose which we really desire'.", "bio": "Norbert Wiener (1894–1964) was an MIT mathematician and child prodigy whose work on stochastic processes, filtering and feedback founded cybernetics, the study of control and communication in animals and machines ('Cybernetics', 1948). He was among the first to theorise that intelligent behaviour arises from feedback that machines could simulate, influencing von Neumann, Shannon, Mead and Bateson. Wiener was also one of the first public voices on the social risks of automation. In 'The Human Use of Human Beings' (1950) and especially his 1960 Science essay 'Some Moral and Technical Consequences of Automation', he warned that learning machines could act faster than humans can correct them, invoking the Sorcerer's Apprentice and the Monkey's Paw. His line that we must be sure 'the purpose put into the machine is the purpose which we really desire and not merely a colorful imitation of it' is widely cited, including by Stuart Russell, as the first clear statement of the value-alignment problem. 'God & Golem, Inc.' (1964) won a posthumous National Book Award.", "key_ideas": ["cybernetics and feedback control", "value alignment ('the purpose put into the machine')", "the Sorcerer's Apprentice problem", "human speed too slow to correct fast machines", "social and labour effects of automation"], "key_works": [{"title": "Cybernetics: Or Control and Communication in the Animal and the Machine", "year": 1948, "url": "https://en.wikipedia.org/wiki/Cybernetics:_Or_Control_and_Communication_in_the_Animal_and_the_Machine"}, {"title": "The Human Use of Human Beings", "year": 1950, "url": "https://en.wikipedia.org/wiki/The_Human_Use_of_Human_Beings"}, {"title": "Some Moral and Technical Consequences of Automation (Science 131:1355)", "year": 1960, "url": "https://www.cs.umd.edu/users/gasarch/BLOGPAPERS/moral.pdf"}, {"title": "God & Golem, Inc.", "year": 1964, "url": "https://en.wikipedia.org/wiki/God_%26_Golem,_Inc."}], "quotes": [{"text": "If we use, to achieve our purposes, a mechanical agency with whose operation we cannot efficiently interfere once we have started it, because the action is so fast and irrevocable that we have not the data to intervene before the action is complete, then we had better be quite sure that the purpose put into the machine is the purpose which we really desire and not merely a colorful imitation of it.", "context": "'Some Moral and Technical Consequences of Automation', Science, 6 May 1960", "source_url": "https://www.cs.umd.edu/users/gasarch/BLOGPAPERS/moral.pdf"}, {"text": "Similarly, when a machine constructed by us is capable of operating on its incoming data at a pace which we cannot keep, we may not know, until too late, when to turn it off.", "context": "Same Science essay (6 May 1960)", "source_url": "https://www.cs.umd.edu/users/gasarch/BLOGPAPERS/moral.pdf"}, {"text": "By the very slowness of our human activities, our effective control of our machines may be nullified.", "context": "'Revolt of the Machines', Time, 11 January 1960 (as given on Wikiquote)", "source_url": "https://en.wikiquote.org/wiki/Norbert_Wiener"}, {"text": "The world of the future will be an ever more demanding struggle against the limitations of our intelligence, not a comfortable hammock in which we can lie down to be waited upon by our robot slaves.", "context": "God & Golem, Inc. (1964), p. 69 (as given on Wikiquote)", "source_url": "https://en.wikiquote.org/wiki/Norbert_Wiener"}], "interviews": [{"title": "Norbert Wiener – Men, Machines, and the World About Them (1950)", "outlet": "YouTube (archival audio)", "year": 1950, "url": "https://www.youtube.com/watch?v=QJWDJvbea0M", "youtube_id": "QJWDJvbea0M"}, {"title": "Norbert Wiener – The Application of Physics to Medicine (1953)", "outlet": "YouTube (archival audio)", "year": 1953, "url": "https://www.youtube.com/watch?v=_nAn-QH6syM", "youtube_id": "_nAn-QH6syM"}, {"title": "'Machines Smarter Than Men?' Interview with Dr. Norbert Wiener (U.S. News & World Report)", "outlet": "U.S. National Library of Medicine — Profiles in Science", "year": 1964, "url": "https://profiles.nlm.nih.gov/spotlight/bb/catalog/nlm:nlmuid-101584906X7699-doc"}], "links": {"website": "", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Norbert_Wiener", "github": "", "substack": ""}, "p_doom_or_stance": "Warned that fast, literal-minded machines could pursue the wrong purpose before humans could intervene; no probability given.", "honours": ["National Medal of Science (1963)", "Bôcher Memorial Prize (1933)", "National Book Award (1965, posthumous) for God & Golem, Inc."], "photo": "norbert-wiener.jpg"}, {"slug": "i-j-good", "name": "I. J. Good", "category": "pioneer-public-voice", "current_role": "Historical figure (1916–2009); statistician, Bletchley Park codebreaker, originator of the 'intelligence explosion'", "orgs_history": ["Bletchley Park, with Alan Turing (WWII)", "University of Manchester (computer design, Bayesian statistics)", "Virginia Tech, University Distinguished Professor of Statistics"], "country": "United Kingdom / United States", "known_for": "Coined the 'intelligence explosion' (1965): the first ultraintelligent machine is the last invention we need, 'provided that the machine is docile enough'.", "bio": "Irving John Good (born Isadore Jacob Gudak, 1916–2009) was a British mathematician who worked as a cryptologist alongside Alan Turing at Bletchley Park and afterwards with Turing at Manchester on early computers and Bayesian statistics, before moving to Virginia Tech. He is best known in AI safety for his 1965 paper 'Speculations Concerning the First Ultraintelligent Machine', which argued that a machine able to surpass all human intellectual activity could design better machines, triggering an 'intelligence explosion' that would leave human intelligence far behind. Crucially, he added the caveat that this would be humanity's last invention only 'provided that the machine is docile enough to tell us how to keep it under control', anticipating today's control problem. Good also advised Stanley Kubrick on supercomputers for '2001: A Space Odyssey'. His intelligence-explosion argument underlies modern discussions of recursive self-improvement and the technological singularity.", "key_ideas": ["intelligence explosion", "ultraintelligent machine", "recursive self-improvement", "docility / controllability", "Bayesian statistics"], "key_works": [{"title": "Speculations Concerning the First Ultraintelligent Machine (Advances in Computers vol. 6)", "year": 1965, "url": "https://vtechworks.lib.vt.edu/handle/10919/89424"}, {"title": "Good Thinking: The Foundations of Probability and Its Applications", "year": 1983, "url": "https://en.wikipedia.org/wiki/I._J._Good"}], "quotes": [{"text": "Let an ultraintelligent machine be defined as a machine that can far surpass all the intellectual activities of any man however clever. Since the design of machines is one of these intellectual activities, an ultraintelligent machine could design even better machines; there would then unquestionably be an \"intelligence explosion\", and the intelligence of man would be left far behind. Thus the first ultraintelligent machine is the last invention that man need ever make, provided that the machine is docile enough to tell us how to keep it under control.", "context": "'Speculations Concerning the First Ultraintelligent Machine' (1965/66)", "source_url": "https://en.wikiquote.org/wiki/I._J._Good"}, {"text": "It is curious that this point is made so seldom outside of science fiction. It is sometimes worthwhile to take science fiction seriously.", "context": "Same paper, immediately following the intelligence-explosion passage", "source_url": "https://en.wikiquote.org/wiki/I._J._Good"}, {"text": "There may be occasions when it is best to behave irrationally, but whether there are should be decided rationally.", "context": "Good Thinking (1983), first paragraph", "source_url": "https://en.wikiquote.org/wiki/I._J._Good"}, {"text": "I thought neural networks, with their ultraparallel working, were as likely as programming to lead to an intelligent machine, but brains use both methods; they have parallel architecture and also use language and reasoning.", "context": "'A Conversation with I. J. Good', Statistical Science (1996), on writing 'Speculations Concerning the First Ultraintelligent Machine'", "source_url": "https://www.stat.vt.edu/content/dam/stat_vt_edu/graphics-and-pdfs/emeritus-interviews-and-papers/Good/Conversation-with-IJGood.pdf"}], "interviews": [{"title": "A Conversation with I. J. Good (interview by David L. Banks, recorded Dec 1993)", "outlet": "Statistical Science 11(1), 1996", "year": 1996, "url": "https://www.stat.vt.edu/content/dam/stat_vt_edu/graphics-and-pdfs/emeritus-interviews-and-papers/Good/Conversation-with-IJGood.pdf"}], "links": {"website": "", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/I._J._Good", "github": "", "substack": ""}, "p_doom_or_stance": "Optimistic about ultraintelligence but conditioned it on the machine being 'docile enough to tell us how to keep it under control'.", "honours": [], "photo": "i-j-good.jpg"}, {"slug": "nick-bostrom", "name": "Nick Bostrom", "category": "pioneer-public-voice", "current_role": "Founder and Principal Researcher, Macrostrategy Research Initiative (as of 2026)", "orgs_history": ["Professor and Founding Director, Future of Humanity Institute, University of Oxford (2005–2024; institute closed April 2024)", "Co-founder, World Transhumanist Association (1998)"], "country": "Sweden", "known_for": "Author of 'Superintelligence' (2014), the book that put the AI control problem into the mainstream; coined much of the existential-risk vocabulary.", "bio": "Nick Bostrom (born Niklas Boström, 1973) is a Swedish-born philosopher with a background in physics, computational neuroscience, logic and AI. He founded and for nearly two decades directed Oxford's Future of Humanity Institute (2005–2024), which incubated much early AI-safety and existential-risk research before closing in 2024. He now leads his own nonprofit, the Macrostrategy Research Initiative. Bostrom introduced or framed many ideas now standard in the field: existential risk as a global priority, the simulation argument, the orthogonality thesis and instrumental convergence, the vulnerable world hypothesis and the unilateralist's curse. His 2014 bestseller 'Superintelligence: Paths, Dangers, Strategies' argued that a machine intelligence exceeding humans 'in virtually all domains of interest' could be humanity's last challenge and that solving the control and value-loading problems must come first; it influenced Bill Gates, Elon Musk and many lab founders. His 2024 book 'Deep Utopia' turns to what a good post-superintelligence world could look like. In 2025–26 interviews he has argued for keeping the ability to slow frontier AI rather than an indefinite pause.", "key_ideas": ["superintelligence and the control problem", "orthogonality thesis", "instrumental convergence", "existential risk as global priority", "value-loading problem", "vulnerable world hypothesis", "simulation argument", "moral status of digital minds"], "key_works": [{"title": "Existential Risks: Analyzing Human Extinction Scenarios", "year": 2002, "url": "https://nickbostrom.com/existential/risks"}, {"title": "Superintelligence: Paths, Dangers, Strategies", "year": 2014, "url": "https://en.wikipedia.org/wiki/Superintelligence:_Paths,_Dangers,_Strategies"}, {"title": "The Vulnerable World Hypothesis", "year": 2019, "url": "https://nickbostrom.com/papers/vulnerable.pdf"}, {"title": "Deep Utopia: Life and Meaning in a Solved World", "year": 2024, "url": "https://nickbostrom.com/deep-utopia"}], "quotes": [{"text": "Before the prospect of an intelligence explosion, we humans are like small children playing with a bomb. Such is the mismatch between the power of our plaything and the immaturity of our conduct.", "context": "Superintelligence (2014), ch. 15 (as given on Wikiquote)", "source_url": "https://en.wikiquote.org/wiki/Nick_Bostrom"}, {"text": "In this book, I try to understand the challenge presented by the prospect of superintelligence, and how we might best respond. This is quite possibly the most important and most daunting challenge humanity has ever faced. And—whether we succeed or fail—it is probably the last challenge we will ever face.", "context": "Superintelligence (2014), preface (as given on Wikiquote)", "source_url": "https://en.wikiquote.org/wiki/Nick_Bostrom"}, {"text": "Solving the value-loading problem is a research challenge worthy of some of the next generation’s best mathematical talent. We cannot postpone confronting this problem until the AI has developed enough reason to easily understand our intentions.", "context": "Superintelligence (2014), ch. 12 (as given on Wikiquote)", "source_url": "https://en.wikiquote.org/wiki/Nick_Bostrom"}, {"text": "Machine intelligence is the last invention that humanity will ever need to make.", "context": "TED2015 talk 'What happens when our computers get smarter than we are?' (as quoted on the TED talk page)", "source_url": "https://www.ted.com/talks/nick_bostrom_what_happens_when_our_computers_get_smarter_than_we_are/transcript"}, {"text": "The world is quickening, and the birth of superintelligence presumably not very far off.", "context": "His personal homepage, current as of October 2026", "source_url": "https://nickbostrom.com/"}], "interviews": [{"title": "What happens when our computers get smarter than we are?", "outlet": "TED", "year": 2015, "url": "https://www.ted.com/talks/nick_bostrom_what_happens_when_our_computers_get_smarter_than_we_are", "youtube_id": "MnT1xgZgkpk"}, {"title": "#83 – Nick Bostrom: Simulation and Superintelligence", "outlet": "Lex Fridman Podcast", "year": 2020, "url": "https://lexfridman.com/nick-bostrom/"}, {"title": "Interview with Nick Bostrom on Superintelligence & Deep Utopia", "outlet": "Science, Technology & the Future (Adam Ford)", "year": 2025, "url": "https://www.scifuture.org/forthcoming-interview-with-nick-bostrom/"}, {"title": "Nick Bostrom: Worries About AI Existential Risk Just Became More Concrete", "outlet": "Big Technology Podcast", "year": 2026, "url": "https://podcasts.apple.com/us/podcast/nick-bostrom-worries-about-ai-existential-risk-just/id1522960417?i=1000784308833"}, {"title": "We Are Clueless About What’s Coming (Interesting Times)", "outlet": "The New York Times", "year": 2026, "url": "https://www.nytimes.com/2026/10/01/opinion/interesting-times-podcast-spencer-klavan-nick-bostrom.html"}], "links": {"website": "https://nickbostrom.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Nick_Bostrom", "github": "", "substack": ""}, "p_doom_or_stance": "Treats misaligned superintelligence as a major existential risk but also stresses the upside; in 2025–26 favours preserving the ability to slow or 'pace' frontier development over an indefinite pause (per a16z/MTS episode summaries, Oct 2026).", "honours": ["Superintelligence (2014) was a New York Times bestseller (per nickbostrom.com)"], "photo": "nick-bostrom.jpg"}, {"slug": "toby-ord", "name": "Toby Ord", "category": "pioneer-public-voice", "current_role": "Senior Researcher, Oxford Martin AI Governance Initiative, University of Oxford; board member, Centre for the Governance of AI (as of 2026)", "orgs_history": ["Senior Research Fellow, Future of Humanity Institute, Oxford (until 2024)", "Founder, Giving What We Can (2009)"], "country": "Australia", "known_for": "Author of 'The Precipice' (2020), which rated unaligned AI the single largest existential risk this century (about 1 in 10).", "bio": "Toby Ord (born 1979) is an Australian philosopher at the University of Oxford. He founded Giving What We Can in 2009 and is one of the founders of the effective-altruism movement. His research moved from global-poverty ethics to existential risk at Oxford's Future of Humanity Institute. His 2020 book 'The Precipice: Existential Risk and the Future of Humanity' estimated roughly a 1-in-6 chance of existential catastrophe this century, with unaligned artificial intelligence the largest single contributor at about 1 in 10, ahead of engineered pandemics. He now works at the Oxford Martin AI Governance Initiative and sits on the board of GovAI. Since 2024 he has published closely read analyses of AI trends: inference-time scaling and its implications for governance, a simple 'constant failure rate' model of AI agents' task horizons, and essays revisiting The Precipice, which judged racing between labs bad and improved governance good. In 2026 podcasts (80,000 Hours, FT Rachman Review) he argued recursive self-improvement probably will not ignite an immediate intelligence explosion, while still treating AI as the top existential risk.", "key_ideas": ["existential risk", "longtermism", "AI as the largest existential risk this century", "inference scaling and AI governance", "task-horizon / half-life model of AI agents", "effective giving"], "key_works": [{"title": "The Precipice: Existential Risk and the Future of Humanity", "year": 2020, "url": "https://www.theprecipice.com/"}, {"title": "The Precipice Revisited", "year": 2024, "url": "https://www.tobyord.com/writing/the-precipice-revisited"}, {"title": "Inference Scaling Reshapes AI Governance", "year": 2025, "url": "https://www.tobyord.com/"}], "quotes": [{"text": "And this is something where I now think that the risk is high enough, that this century, it’s about one in six.", "context": "80,000 Hours podcast on The Precipice (March 2020), on total existential risk this century", "source_url": "https://80000hours.org/podcast/episodes/toby-ord-the-precipice-existential-risk-future-humanity/"}, {"text": "While there is by no means universal agreement, the idea that existential risk from AI is a major global priority is now a respected standard position by many leaders in AI and global politics, as is the need for national and international regulation of frontier AI.", "context": "Essay 'The Precipice Revisited' (July 2024)", "source_url": "https://www.tobyord.com/writing/the-precipice-revisited"}, {"text": "We had long been aware of the possibilities and dangers of racing: that it would lead to cutting corners in safety in an attempt to get to advanced AGI before anyone else.", "context": "'The Precipice Revisited' (2024)", "source_url": "https://www.tobyord.com/writing/the-precipice-revisited"}], "interviews": [{"title": "Toby Ord on the precipice and humanity's potential futures", "outlet": "80,000 Hours", "year": 2020, "url": "https://80000hours.org/podcast/episodes/toby-ord-the-precipice-existential-risk-future-humanity/"}, {"title": "Toby Ord on graphs AI companies would prefer you didn't (fully) understand", "outlet": "80,000 Hours", "year": 2025, "url": "https://80000hours.org/podcast/episodes/toby-ord-inference-scaling-ai-governance/"}, {"title": "#250 – Toby Ord on where AGI timelines go wrong", "outlet": "80,000 Hours", "year": 2026, "url": "https://80000hours.org/podcast/episodes/toby-ord-recursive-self-improvement-agi-timelines/"}, {"title": "Could AI really end humanity? (The Rachman Review)", "outlet": "Financial Times", "year": 2026, "url": "https://www.ft.com/content/e6f7ac91-8741-4b90-ab23-a6b4f7c9e348"}, {"title": "Crucial Updates on the Evolving AGI Risk Landscape (AGI Governance, Ep. 7)", "outlet": "The Trajectory (Daniel Faggella)", "year": 2025, "url": "https://danfaggella.com/ord1/"}], "links": {"website": "https://www.tobyord.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Toby_Ord", "github": "", "substack": ""}, "p_doom_or_stance": "The Precipice (2020): ~1 in 6 total existential risk this century; ~1 in 10 from unaligned AI (80,000 Hours 2020 episode). Still called AI the biggest, if most uncertain, existential risk in 2025.", "honours": [], "photo": "toby-ord.jpg"}, {"slug": "stephen-hawking", "name": "Stephen Hawking", "category": "pioneer-public-voice", "current_role": "Historical figure (1942–2018); theoretical physicist, Lucasian Professor of Mathematics at Cambridge (1979–2009)", "orgs_history": ["Lucasian Professor of Mathematics, University of Cambridge (1979–2009)", "Director of Research, Centre for Theoretical Cosmology, Cambridge", "Advisory board, Future of Life Institute; spoke at launch of Leverhulme Centre for the Future of Intelligence (2016)"], "country": "United Kingdom", "known_for": "The world's most famous scientist to warn that 'full artificial intelligence could spell the end of the human race'.", "bio": "Stephen Hawking (1942–2018) was an English theoretical physicist and cosmologist, best known for work with Roger Penrose on singularities, the prediction that black holes emit radiation, and the bestseller 'A Brief History of Time'. Diagnosed with motor neurone disease at 21, he communicated for decades through a speech-generating device, which itself used a basic form of AI. In his last years he became the most prominent scientific voice on AI risk. In May 2014 he co-wrote, with Stuart Russell, Max Tegmark and Frank Wilczek, an op-ed warning that creating AI could be 'the biggest event in human history' and 'might also be the last'. In a December 2014 BBC interview he said full AI 'could spell the end of the human race', and in 2015 he signed the Future of Life Institute open letter on research priorities for robust and beneficial AI. Launching Cambridge's Leverhulme Centre for the Future of Intelligence in 2016, he said powerful AI would be 'either the best, or the worst thing, ever to happen to humanity'. His final book, 'Brief Answers to the Big Questions' (2018), includes a chapter on whether AI will outsmart us.", "key_ideas": ["AI as potential end of the human race", "long-term impact depends on whether AI can be controlled at all", "need for AI safety research (2015 FLI letter)", "autonomous weapons risk"], "key_works": [{"title": "'Transcendence looks at the implications of artificial intelligence — but are we taking AI seriously enough?' (Independent op-ed with Russell, Tegmark, Wilczek)", "year": 2014, "url": "https://www.independent.co.uk/news/science/stephen-hawking-transcendence-looks-at-the-implications-of-artificial-intelligence-but-are-we-taking-ai-seriously-enough-9313474.html"}, {"title": "Research Priorities for Robust and Beneficial AI: An Open Letter (signatory)", "year": 2015, "url": "https://futureoflife.org/open-letter/ai-open-letter/"}, {"title": "Brief Answers to the Big Questions (ch. 9, 'Will artificial intelligence outsmart us?')", "year": 2018, "url": "https://en.wikipedia.org/wiki/Brief_Answers_to_the_Big_Questions"}], "quotes": [{"text": "The development of full artificial intelligence could spell the end of the human race.", "context": "BBC interview, 2 December 2014", "source_url": "https://www.bbc.com/news/technology-30290540"}, {"text": "It would take off on its own, and re-design itself at an ever increasing rate. Humans, who are limited by slow biological evolution, couldn't compete, and would be superseded.", "context": "Same BBC interview (2014)", "source_url": "https://www.bbc.com/news/technology-30290540"}, {"text": "Success in creating AI would be the biggest event in human history. Unfortunately, it might also be the last, unless we learn how to avoid the risks.", "context": "Independent op-ed co-written with Stuart Russell, Max Tegmark and Frank Wilczek, 1 May 2014 (standfirst)", "source_url": "https://www.independent.co.uk/news/science/stephen-hawking-transcendence-looks-at-the-implications-of-artificial-intelligence-but-are-we-taking-ai-seriously-enough-9313474.html"}, {"text": "Whereas the short-term impact of AI depends on who controls it, the long-term impact depends on whether it can be controlled at all.", "context": "Same Independent op-ed (2014)", "source_url": "https://www.independent.co.uk/news/science/stephen-hawking-transcendence-looks-at-the-implications-of-artificial-intelligence-but-are-we-taking-ai-seriously-enough-9313474.html"}, {"text": "In short, the rise of powerful AI will be either the best, or the worst thing, ever to happen to humanity. We do not yet know which.", "context": "Speech launching the Leverhulme Centre for the Future of Intelligence, Cambridge, 19 October 2016", "source_url": "https://www.cam.ac.uk/research/news/the-best-or-worst-thing-to-happen-to-humanity-stephen-hawking-launches-centre-for-the-future-of"}], "interviews": [{"title": "Stephen Hawking warns artificial intelligence could end mankind", "outlet": "BBC News (interview with Rory Cellan-Jones)", "year": 2014, "url": "https://www.bbc.com/news/technology-30290540"}, {"title": "'The best or worst thing to happen to humanity' — launch speech, Leverhulme Centre for the Future of Intelligence", "outlet": "University of Cambridge", "year": 2016, "url": "https://www.cam.ac.uk/research/news/the-best-or-worst-thing-to-happen-to-humanity-stephen-hawking-launches-centre-for-the-future-of"}, {"title": "Questioning the universe", "outlet": "TED", "year": 2008, "url": "https://www.ted.com/talks/stephen_hawking_questioning_the_universe"}], "links": {"website": "https://www.hawking.org.uk/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Stephen_Hawking", "github": "", "substack": ""}, "p_doom_or_stance": "Warned full AI 'could spell the end of the human race' (BBC, 2014); no numeric estimate.", "honours": ["Presidential Medal of Freedom (2009)", "Copley Medal, Royal Society (2006)", "Wolf Prize in Physics (1988)", "Fundamental Physics Prize (2013)"], "photo": "stephen-hawking.jpg"}, {"slug": "jaan-tallinn", "name": "Jaan Tallinn", "category": "pioneer-public-voice", "current_role": "Co-founder, Future of Life Institute and Centre for the Study of Existential Risk; AI-safety philanthropist and investor (Metaplanet); UN AI Advisory Body member; board, Center for AI Safety (as of 2025–26)", "orgs_history": ["Founding engineer, Skype and Kazaa/FastTrack", "Early investor and board member, DeepMind", "Led Anthropic's $124m Series A (2021)", "EU High-Level Expert Group on AI (former member)"], "country": "Estonia", "known_for": "Skype co-founder who became the AI-safety movement's best-known funder and co-founded CSER and FLI.", "bio": "Jaan Tallinn (born 1972) is an Estonian programmer and investor who helped build Kazaa and Skype. After reading Eliezer Yudkowsky's writing around 2009 he turned to existential risk, and has since become one of the largest private funders of AI-safety work. He co-founded the Centre for the Study of Existential Risk at Cambridge (with Martin Rees and Huw Price) and the Future of Life Institute, and supports many other safety organisations through grant-making. He was an early investor and board member at DeepMind and led Anthropic's 2021 Series A, explaining that you have to study the strongest models to understand them. He serves on the UN's AI Advisory Body, the board of the Center for AI Safety, and the Bulletin of the Atomic Scientists' Board of Sponsors. Tallinn signed the 2023 pause letter and the CAIS extinction-risk statement, and argues that the burden of proof should be on companies, that governments need the ability to slow or stop dangerous training runs, and that we might be heading for 'a future where AI no longer needs humans'.", "key_ideas": ["AI as an environmental risk to humanity", "pause / slowdown of frontier AI", "burden of proof on developers", "compute and datacenter governance", "funding the safety ecosystem"], "key_works": [{"title": "Existential Risk (Edge conversation)", "year": 2015, "url": "https://www.edge.org/conversation/jaan_tallinn-existential-risk"}, {"title": "Pause Giant AI Experiments: An Open Letter (signatory/FLI co-founder)", "year": 2023, "url": "https://futureoflife.org/open-letter/pause-giant-ai-experiments/"}], "quotes": [{"text": "The main argument basically is that we might be heading for a future where AI no longer needs humans. And by that, I mean we might get a self-sustaining AI, AI that can build its own infrastructure, can do its own improvements without any need from, from human, any help from humans. And in fact, humans might be too slow for it.", "context": "Manifold podcast with Steve Hsu, episode #112 (May 2026), transcript", "source_url": "https://www.manifold1.com/episodes/ai-billionaire-on-existential-risk-jaan-tallinn/transcript"}, {"text": "I believe we are racing towards a dangerous precipice with AI development, and part of the danger is that we do not know exactly where the cliff edge is.", "context": "CogX interview (2024), as republished on blog.biocomm.ai", "source_url": "https://blog.biocomm.ai/2024/10/03/will-ai-take-over-a-conversation-with-jaan-tallinn-cogxnewsletters/"}, {"text": "The thing about AI is, if you're creating machines that are more and more intelligent, you don't want to inadvertently end up in a situation that gorillas are these days, for example, that you have a smarter agent than you dominating the environment.", "context": "Edge.org conversation 'Existential Risk' (2015)", "source_url": "https://www.edge.org/conversation/jaan_tallinn-existential-risk"}], "interviews": [{"title": "AI Billionaire on Existential Risk: Jaan Tallinn – #112", "outlet": "Manifold (Steve Hsu)", "year": 2026, "url": "https://www.youtube.com/watch?v=6MaUZ4Hi7os", "youtube_id": "6MaUZ4Hi7os"}, {"title": "Jaan Tallinn would like us to survive", "outlet": "The Generalist (Mario Gabriele)", "year": 2026, "url": "https://www.generalist.com/p/jaan-tallinn-would-like-us-to-survive"}, {"title": "The Case for a Pause Before We Birth AGI (AGI Destinations, Ep. 2)", "outlet": "The Trajectory (Daniel Faggella)", "year": 2024, "url": "https://danfaggella.com/tallinn1/"}, {"title": "Jaan Tallinn on thinking from first principles", "outlet": "CSER", "year": 2015, "url": "https://www.cser.ac.uk/work/jaan-tallinn-on-thinking-from-first-principles"}], "links": {"website": "https://futureoflife.org/person/jaan-tallinn", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Jaan_Tallinn", "github": "", "substack": ""}, "p_doom_or_stance": "Advocates a pause/slowdown on frontier AI; says he has yet to meet anyone at AI labs who puts the risk of the next-generation model 'blowing up the planet' below 1% (per Wikipedia, citing his remarks).", "honours": [], "photo": "jaan-tallinn.jpg"}]);
